import React, { useState, useRef, useEffect, useCallback } from 'react';
import {
    Plus, Upload, Search, X, ZoomIn, ZoomOut, Grid, Trash2, Edit
} from 'lucide-react';

const colors = {
    primary: '#ff3d7f',
    secondary: '#121212',
    secondaryLight: '#212121',
    light: '#ffffff',
    midGray: '#868686',
    accent: '#00dbdd',
    successGreen: '#4ADE80',
    warningOrange: '#dc6300',
    errorRed: '#FF3D3D'
};

const ConceptBoard = () => {
    const [conceptArt, setConceptArt] = useState([]);
    const [selectedConcept, setSelectedConcept] = useState(null);
    const [scale, setScale] = useState(1);
    const [boardOffset, setBoardOffset] = useState({ x: 0, y: 0 });
    const [isDraggingBoard, setIsDraggingBoard] = useState(false);
    const [dragStartPos, setDragStartPos] = useState({ x: 0, y: 0 });
    const [showUploadModal, setShowUploadModal] = useState(false);
    const boardRef = useRef(null);
    const fileInputRef = useRef(null);
    const nextId = useRef(1);

    useEffect(() => {
        const storedConcepts = localStorage.getItem('conceptBoard_concepts');
        if (storedConcepts) {
            const parsed = JSON.parse(storedConcepts);
            setConceptArt(parsed);
            nextId.current = Math.max(...parsed.map(c => c.id), 0) + 1;
        }
    }, []);

    useEffect(() => {
        localStorage.setItem('conceptBoard_concepts', JSON.stringify(conceptArt));
    }, [conceptArt]);

    const handleUploadClick = () => {
        fileInputRef.current?.click();
    };

    const handleFileSelect = (e) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;

        Array.from(files).forEach(file => {
            const reader = new FileReader();
            reader.onload = (event) => {
                const newConcept = {
                    id: nextId.current++,
                    name: file.name.split('.')[0],
                    thumbnail: event.target.result,
                    position: { x: 0, y: 0 },
                    scale: 1
                };
                setConceptArt(prev => [...prev, newConcept]);
            };
            reader.readAsDataURL(file);
        });
    };

    const handleBoardMouseDown = (e) => {
        if (e.target === boardRef.current) {
            setIsDraggingBoard(true);
            setDragStartPos({ x: e.clientX, y: e.clientY });
        }
    };

    const handleBoardMouseMove = (e) => {
        if (!isDraggingBoard) return;
        const dx = e.clientX - dragStartPos.x;
        const dy = e.clientY - dragStartPos.y;
        setBoardOffset(prev => ({ x: prev.x + dx, y: prev.y + dy }));
        setDragStartPos({ x: e.clientX, y: e.clientY });
    };

    const handleBoardMouseUp = () => {
        setIsDraggingBoard(false);
    };

    const handleBoardWheel = (e) => {
        e.preventDefault();
        const zoomFactor = 0.1;
        const newScale = Math.max(0.1, Math.min(3, scale - e.deltaY * zoomFactor * 0.01));
        setScale(newScale);
    };

    return (
        <div style={{ backgroundColor: colors.secondary }} className="h-screen w-screen flex flex-col items-center justify-center p-4">
            <div className="mb-4 w-full flex justify-between items-center">
                <h1 className="text-white text-xl font-bold">Concept Board</h1>
                <button
                    className="bg-pink-500 text-white px-4 py-2 rounded hover:bg-pink-600"
                    onClick={handleUploadClick}
                >
                    <Upload className="inline w-4 h-4 mr-2" /> Upload
                </button>
                <input
                    type="file"
                    ref={fileInputRef}
                    style={{ display: 'none' }}
                    onChange={handleFileSelect}
                    multiple
                    accept="image/*"
                />
            </div>

            <div
                ref={boardRef}
                onMouseDown={handleBoardMouseDown}
                onMouseMove={handleBoardMouseMove}
                onMouseUp={handleBoardMouseUp}
                onMouseLeave={handleBoardMouseUp}
                onWheel={handleBoardWheel}
                className="bg-gray-800 border border-gray-700 rounded relative overflow-hidden"
                style={{ width: '80vw', height: '80vh', cursor: isDraggingBoard ? 'grabbing' : 'grab' }}
            >
                <div
                    style={{
                        transform: `translate(${boardOffset.x}px, ${boardOffset.y}px) scale(${scale})`,
                        transformOrigin: 'top left',
                        position: 'absolute',
                        width: 'max-content',
                        height: 'max-content'
                    }}
                >
                    {conceptArt.map(concept => (
                        <div
                            key={concept.id}
                            style={{
                                position: 'absolute',
                                top: concept.position.y,
                                left: concept.position.x,
                                transform: `scale(${concept.scale})`
                            }}
                        >
                            <img
                                src={concept.thumbnail}
                                alt={concept.name}
                                className="w-48 h-48 object-cover border border-white rounded"
                            />
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default ConceptBoard;
